import csv, re, datetime, collections

rows=list(csv.DictReader(open('expenses.csv',newline='')))
print(len(rows))

def parse_date(s):
    s=s.strip()
    for fmt in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y'):
        try: return datetime.datetime.strptime(s,fmt).date()
        except ValueError: pass
    raise ValueError(s)

def parse_amt(s):
    s=s.strip().replace('USD','').replace('$','').replace(',','').strip()
    return int(round(float(s)*100))

catmap={'taxi':'Travel','uber':'Travel','flight':'Travel','hotel':'Lodging','airbnb':'Lodging',
        'lunch':'Meals','dinner':'Meals','coffee':'Meals','saas':'Software','software':'Software',
        'license':'Software','books':'Learning','course':'Learning'}

seen={}
for r in rows:
    i=r['id'].strip()
    if i in seen: continue
    seen[i]=r

oct_rows=[]
for i,r in seen.items():
    d=parse_date(r['date'])
    if r['status'].strip().lower()=='void': continue
    if d.year==2026 and d.month==10:
        oct_rows.append((i,d,r['category'],parse_amt(r['amount'])))

print('oct count',len(oct_rows))
agg=collections.defaultdict(lambda:[0,0])
flags=[]
for i,d,c,a in oct_rows:
    key=c.strip().lower()
    cat=catmap[key]
    agg[cat][0]+=1
    agg[cat][1]+=a
    if a>50000: flags.append((int(i),a))
total=sum(v[1] for v in agg.values())
print('total',total, total/100)
for k,v in sorted(agg.items(), key=lambda kv:-kv[1][1]):
    print(k,v[0],v[1],v[1]/100)
print('flags',sorted(flags))
print('sum check',sum(v[1] for v in agg.values())==total)
# excluded october reasons
for i,r in seen.items():
    d=parse_date(r['date'])
    if d.year==2026 and d.month==10 and r['status'].strip().lower()=='void':
        print('void oct',i,r['amount'])
EOF", "description": "Compute October expense aggregates"}

